diff --git a/internal/terraform/marks.go b/internal/terraform/marks.go
index e57c4745fa..de90dfe130 100644
--- a/internal/terraform/marks.go
+++ b/internal/terraform/marks.go
@@ -64,17 +64,23 @@ func marksEqual(a, b []cty.PathValueMarks) bool {
 // the PathValueMarks within this package too.
 func dedupePathValueMarks(m []cty.PathValueMarks) []cty.PathValueMarks {
 	var res []cty.PathValueMarks
-	// we'll use a GoString format key to differentiate PathValueMarks, since
-	// the Path portion is not automagically comparable.
-	seen := make(map[string]bool)

+	// Deduplicate by semantic equality rather than by stringifying the
+	// PathValueMarks. The %#v representation of cty.PathValueMarks can vary
+	// for logically-equal path steps (notably index keys) which would cause
+	// spurious differences to be retained. Use the Equal method on
+	// PathValueMarks to determine duplicates.
 	for _, pvm := range m {
-		key := fmt.Sprintf("%#v", pvm)
-		if _, ok := seen[key]; ok {
-			continue
+		found := false
+		for _, existing := range res {
+			if existing.Equal(pvm) {
+				found = true
+				break
+			}
+		}
+		if !found {
+			res = append(res, pvm)
 		}
-		seen[key] = true
-		res = append(res, pvm)
 	}

 	return res

