diff --git a/internal/states/statefile/version4.go b/internal/states/statefile/version4.go
index f3b21c6028..d6ccd2d04d 100644
--- a/internal/states/statefile/version4.go
+++ b/internal/states/statefile/version4.go
@@ -489,8 +489,23 @@ func appendInstanceObjectStateV4(rs *states.Resource, is *states.ResourceInstanc
 	}

 	// Extract paths from path value marks
+	// Historically we did not persist marks that only referred to the
+	// top-level attribute (a single get_attr step). Persisting such
+	// top-level-only marks for collection-valued attributes (for
+	// example a set of nested blocks) can cause spurious diffs when the
+	// provider or config reconstructs the value without reproducing an
+	// identical top-level mark. To maintain backwards compatibility and
+	// avoid needless diffs, filter out any paths that are a single
+	// get_attr step (i.e. they reference only the attribute itself and
+	// no nested element).
 	var paths []cty.Path
 	for _, vm := range obj.AttrSensitivePaths {
+		if len(vm.Path) == 1 {
+			switch vm.Path[0].(type) {
+			case cty.GetAttrStep:
+				continue
+			}
+		}
 		paths = append(paths, vm.Path)
 	}

