            // we should return the root (only once) instead of peeking the stacks
            // which would throw EmptyStackException.
            if (nodesStack.empty()) {
                hasNext = false;
                return root;
            }
            final List<Node> nodes = nodesStack.peek();
            final int cursor = cursorStack.peek();
            final boolean levelHasNext = cursor < nodes.size();
            if (levelHasNext) {
                Node node = nodes.get(cursor);
                fillStackToLeaf(node);
                return nextFromLevel();
            }
            nodesStack.pop();
            cursorStack.pop();
            hasNext = !nodesStack.empty();
            if (hasNext) {
                return nextFromLevel();
            }
            hasNext = false;
            return root;
        }

