        $shortSymbol = substr($symbol, strrpos($symbol, '\\') + 1);
        $importedShortNames = array_map(
            static fn (string $name): string => strtolower($name),
            array_values($uses)
        );

        // If symbol
        if (\in_array(strtolower($shortSymbol), $importedShortNames, true)) {
            return;
