use std::ffi::OsStr;
use std::path::Path;
use std::sync::RwLock;

use lazy_static::lazy_static;

use crate::error::*;

const DEFAULT_IGNORED_SUFFIXES: [&str; 13] = [
    // Editor etc backups
    "~",
    ".bak",
    ".old",
    ".orig",
    // Debian and derivatives apt/dpkg/ucf backups
    ".dpkg-dist",
    ".dpkg-old",
    ".ucf-dist",
    ".ucf-new",
    ".ucf-old",
    // Red Hat and derivatives rpm backups
    ".rpmnew",
    ".rpmorig",
    ".rpmsave",
    // Build system input/template files
    ".in",
];

lazy_static! {
    // Additional suffixes configured at runtime (via CLI/config file).
    static ref EXTRA_IGNORED_SUFFIXES: RwLock<Vec<String>> = RwLock::new(Vec::new());
}

/// Add additional ignored suffixes which will be considered when stripping
/// filename suffixes during syntax detection. The provided iterator yields
/// owned Strings (e.g. from clap values or configuration file parsing).
pub fn add_ignored_suffixes<I: IntoIterator<Item = String>>(iter: I) {
    let mut extra = EXTRA_IGNORED_SUFFIXES.write().expect("poisoned lock");
    for s in iter {
        // Avoid duplicates
        if !extra.contains(&s) {
            extra.push(s);
        }
    }
}

/// If we find an ignored suffix on the file name, e.g. '~', we strip it and
/// then try again without it.
pub fn try_with_stripped_suffix<T, F>(file_name: &OsStr, func: F) -> Result<Option<T>>
where
    F: Fn(&OsStr) -> Result<Option<T>>,
{
    let mut from_stripped = None;
    if let Some(file_str) = Path::new(file_name).to_str() {
        // First check built-in defaults
        for suffix in &DEFAULT_IGNORED_SUFFIXES {
            if let Some(stripped_filename) = file_str.strip_suffix(suffix) {
                from_stripped = func(OsStr::new(stripped_filename))?;
                break;
            }
        }

        // Then check any extra suffixes configured at runtime
        if from_stripped.is_none() {
            let extra = EXTRA_IGNORED_SUFFIXES.read().expect("poisoned lock");
            for suffix in extra.iter() {
                if let Some(stripped_filename) = file_str.strip_suffix(suffix) {
                    from_stripped = func(OsStr::new(stripped_filename))?;
                    break;
                }
            }
        }
    }
    Ok(from_stripped)
}
