impl<B, E> Future for RouteFuture<B, E> {
    type Output = Result<Response, E>;

    #[inline]
    fn poll(mut self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let strip_body = self.strip_body;
        let allow_header = self.allow_header.take();

        match self.project().future.poll(cx) {
                let mut res = res;

                if strip_body {
                    // If the response doesn't already have a `content-length` header,
                    // try to determine the length from the body and set it. This is
                    // required for correct replies to `HEAD` requests where the body
                    // is removed but the `content-length` header must reflect the
                    // size that would have been sent for a corresponding `GET`.
                    if !res.headers().contains_key(header::CONTENT_LENGTH) {
                        // Use the body's size_hint upper bound when available.
                        if let Some(upper) = res.body().size_hint().upper() {
                            // Safe to unwrap because usize -> decimal string is valid
                            // header value bytes.
                            let val = HeaderValue::from_str(&upper.to_string())
                                .expect("invalid `Content-Length` header value");
                            res.headers_mut().insert(header::CONTENT_LENGTH, val);
                        }
                    }

                    res = res.map(|_| boxed(Empty::new()));
                }

                match allow_header {
                    Some(allow_header) if !res.headers().contains_key(header::ALLOW) => {
                        res.headers_mut().insert(
                            header::ALLOW,
                            HeaderValue::from_maybe_shared(allow_header)
                                .expect("invalid `Allow` header"),
                        );
                    }
                    _ => {}
                }

                Poll::Ready(Ok(res))
            }
            Poll::Ready(Err(err)) => Poll::Ready(Err(err)),
            Poll::Pending => Poll::Pending,
        }
    }
}

