[package]
name = "repro"
version = "0.1.0"
edition = "2021"

[dependencies]
futures = "0.3.31"
tokio = { version = "1.43.0", features = ["rt", "fs", "macros", "io-util"] }
```

I expected to see this happen: `poll = Pending` followed by a successful read of 4096 bytes

