/// Tries to write some bytes from the given `buf` to the writer in an
/// asynchronous manner, returning a future.
pub(crate) fn write_all_buf<'a, W, B>(writer: &'a mut W, buf: &'a mut B) -> WriteAllBuf<'a, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    WriteAllBuf {
        writer,
        buf,
        _pin: PhantomPinned,
    }
}

impl<W, B> Future for WriteAllBuf<'_, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    type Output = io::Result<()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        let me = self.project();
        while me.buf.has_remaining() {
            let n = if me.writer.is_write_vectored() {
                // Use a small fixed array for vectored writes. If the buffer has
                // more chunks than this, `chunks_vectored` will fill up to this
                // many slices and we will write those, then continue the loop
                // to fill more.
                const MAX_BUFS: usize = 8;
                let mut slices = [IoSlice::new(&[]); MAX_BUFS];
                let cnt = me.buf.chunks_vectored(&mut slices);
                // Safety: poll_write_vectored returns a Result<usize>. Use the
                // returned number of bytes written to advance the buffer.
                ready!(Pin::new(&mut *me.writer).poll_write_vectored(cx, &slices[..cnt]))?
            } else {
                ready!(Pin::new(&mut *me.writer).poll_write(cx, me.buf.chunk()))?
            };

            me.buf.advance(n);

            if n == 0 {
                return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
            }
        }

        Poll::Ready(Ok(()))
    }
}
